// Sanitize and normalize inbound customer email payload
const item = $input.first().json;

const rawSubject = item.subject || (item.body && item.body.subject) || "Support Inquiry";
const rawBody = item.text || item.snippet || (item.body && item.body.body) || "";
const senderEmail = item.from || (item.body && item.body.sender_email) || "customer@example.com";
const senderName = item.sender_name || (item.body && item.body.sender_name) || senderEmail.split('@')[0];
const messageId = item.id || item.message_id || (item.body && item.body.message_id) || `<msg-${Date.now()}@customer.org>`;
const threadId = item.threadId || item.thread_id || (item.body && item.body.thread_id) || `thread_${Date.now()}`;

// Normalize subject and strip historical quoted email chains
const cleanSubject = rawSubject.replace(/^(Re:\s*|Fwd:\s*)+/gi, '').trim();
const cleanBody = rawBody.split(/(?i)(^>|\nOn .* wrote:|\n---|\nBest regards|\nThanks,)/)[0].trim();

return [{
  json: {
    message_id: messageId,
    thread_id: threadId,
    sender_email: senderEmail,
    sender_name: senderName,
    clean_subject: cleanSubject,
    clean_body: cleanBody,
    received_at: new Date().toISOString()
  }
}];

