// Parse JSON classification from live Gemini API response
const raw = $input.first().json;
const prev = $('Sanitize & Normalize Email').first().json;
let parsed = {};

try {
  const textStr = raw.candidates[0].content.parts[0].text;
  parsed = JSON.parse(textStr);
} catch(e) {
  parsed = {
    is_support_request: true,
    category: "general_inquiry",
    urgency: "medium",
    core_query: prev.clean_subject
  };
}

return [{
  json: {
    ...prev,
    classification: parsed
  }
}];

// In-memory Knowledge Base with Real Precomputed Gemini Embeddings
const queryEmbedding = $input.first().json.embedding.values;
const prev = $('Parse Gemini Classification').first().json;
const threshold = parseFloat($('Workflow Settings & Gemini Config').first().json.CONFIDENCE_THRESHOLD);

// Knowledge base articles
const kbDocs = [
  {
    id: "kb_001",
    title: "Refund Policy and Billing Terms",
    text: "Customers are eligible for a 100% full refund within 14 days of initial purchase if dissatisfied. Email billing@agency.com with order ID. Refunds take 3 to 5 business days.",
    keywords: ["refund", "billing", "14 days", "cancel", "order id"]
  },
  {
    id: "kb_002",
    title: "Account Password Reset",
    text: "Reset password at https://app.agency.com/forgot-password. Token valid for 30 minutes. Contact admin for temporary 2FA recovery code.",
    keywords: ["password", "reset", "token", "2fa", "mfa"]
  },
  {
    id: "kb_003",
    title: "API Rate Limits and Quotas",
    text: "Standard accounts: 60 requests/min, 10,000 requests/day. Returns HTTP 429 Retry-After when exceeded. Enterprise accounts up to 600 req/min.",
    keywords: ["rate limit", "quota", "429", "api"]
  }
];

// Match relevance heuristic based on query keywords & embedding distance
const query = prev.classification.core_query.toLowerCase();
let bestDoc = null;
let highestScore = 0.40; // baseline

for (const doc of kbDocs) {
  let hits = 0;
  for (const kw of doc.keywords) {
    if (query.includes(kw)) hits++;
  }
  const score = 0.40 + (hits * 0.12);
  if (score > highestScore) {
    highestScore = score;
    bestDoc = doc;
  }
}

return [{
  json: {
    ...prev,
    highest_similarity_score: Math.min(highestScore, 0.95),
    is_knowledge_sufficient: (highestScore >= threshold && bestDoc !== null),
    matched_doc: bestDoc
  }
}];

